/*setUserInfoUpdate*/
UPDATE ICOMLUSR SET USER_NAME_LOC = #{st_user_name}, PURCHASE_DEPT = #{st_purchase_dept_code}, PHONE_NUMBER = #{st_tel_no}, FAX_NUMBER = #{st_fax_no}, MOBILE_PHONE = #{st_mobile_no}, EMAIL = #{st_email}
WHERE COM_CODE = #{st_buyer} AND USER_ID = #{st_user_id}

mapper.select:
/*getBuyerMpSoRecvDateRegisterPop*/
SELECT B.DELIVERY_LT , C.BUYER_ITEM_NO BUYER_ITEM_NO , C.DESCRIPTION DESCRIPTION_LOC , C.SPECIFICATION , CASE NVL((SELECT STD_DATE_FLAG --(N:요구납기일사용 Y:표준납기일사용) FROM KEP_BUYER_FLAG WHERE COM_CODE = A.BUYER ), 'N') WHEN 'N' THEN F_GET_RD_DATE( A.BUYER ) --'요구납기일' ELSE TO_CHAR(SYSDATE + B.DELIVERY_LT, 'YYYYMMDD') --'표준납기일' END RD_DATE --납기요청일
,C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ QUERY
FROM ICOMCART A , ICOMBYIT B , ICOMCQDT C , CMSCATLG D WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{st_user_id}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ IN
#{item}
AND B.CMS_CATLG_ID = D.CMS_CATLG_ID(+) AND D.STD_FLAG(+)='Y'
AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N','Y')
